-- Horario semanal (solo si todavía no se cargó ninguno)
insert into public.horario_semanal (dia, abre, cierra)
  select v.dia, v.abre::time, v.cierra::time from (values (1, '09:00', '20:00'), (2, '09:00', '20:00'), (3, '09:00', '20:00'), (4, '09:00', '20:00'), (5, '09:00', '20:00'), (6, '09:00', '16:00')) as v(dia, abre, cierra)
  where not exists (select 1 from public.horario_semanal);

commit;

select (select count(*) from public.servicios) as servicios, (select count(*) from public.fotos) as fotos, (select count(*) from public.albumes) as albumes, (select count(*) from public.horario_semanal) as franjas_horario;
